import{z as E,x as c,o as t,c as d,q as i,j as l,D as r,d as o,s as n,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"cpufreq governor","description":"","frontmatter":{"title":"cpufreq governor","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpufreq-governor.md","filePath":"cs/cpufreq-governor.md","lastUpdated":1791413859000}'),u={name:"cs/cpufreq-governor.md"};function B(A,e,f,m,h,g){const s=c("Mermaid");return t(),d("div",null,[e[2]||(e[2]=i('<h1 id="cpufreq-governor" tabindex="-1">cpufreq governor <a class="header-anchor" href="#cpufreq-governor" aria-label="Permalink to &quot;cpufreq governor&quot;">​</a></h1><div class="epigraph"><p>governor 根据利用率选 P-state：performance 钉高、powersave 钉低、schedutil 跟调度器的 util 走。</p><footer>—— 据 Linux CPUFreq 文档；ACPI P-state 直觉；[EAS](/cs/eas-scheduling) 为能耗先修</footer></div><p><a href="/cs/fairness-metrics">公平</a> 的实验被频率搅动。<a href="/cs/heterogeneous-core-sched">异构</a> 的容量随频变。缺口是 <strong>cpufreq</strong>：谁决定 MHz，而不是主板 BIOS 百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硬件有离散频率。ondemand：高 util 跳频。schedutil：用 PELT util 直接映射。intel_pstate 可能绕过通用层。缺口：过渡延迟；与 <a href="/cs/napi">NAPI poll</a> 造成假 util；用户 <code>cpufreq-set</code> 与策略冲突。本课不把每家 MSR 列出。</p><p><span class="marginnote">boost/turbo 是更高 P-state，热墙会收回。对象是策略，不是电路。</span></p><p><span class="marginnote">术语翻译：P-state 就是处理器的一档「频率-电压」档位——档位越高算得越快、也越费电；governor 的全部工作，就是在这些离散档位里按策略挑一档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>tick 或更新 util → governor 选 freq → 写 MSR 或 SCMI。对照 <a href="/cs/tx-path-qdisc">qdisc</a>：一个整形包，一个整形瓦特。对照 DL：实时任务常要 performance。对照 memcg：无关直接。</p>',9)),(t(),l(p,null,{default:r(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20UTIL%5B%22CPU%20%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%20--%3E%20GOV%5B%22governor%22%5D%0A%20%20GOV%20--%3E%20F%5B%22%E9%80%89%E9%A2%91%E7%8E%87%22%5D%0A%20%20F%20--%3E%20HW%5B%22P-state%20%E7%94%9F%E6%95%88%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"数字实例：假设 ondemand 每 10 ms 采样一次，负载在第 1 ms 突增，它最迟要等到第 10 ms 才发现并跳频；schedutil 则在调度器每次更新 util 时就地做决定，延迟接近零。这就是「过渡延迟」的具体大小。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"governor 把能耗与延迟的旋钮交给策略，使同一调度器在插电/电池下行为不同。错误的 powersave 把 cyclictest max 打爆。不要写成电费课。与 EAS：选核与选频是一对，分开调会打架。",-1)),(t(),l(p,null,{default:r(()=>[n(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPIKE%5B%22%E5%90%8C%E4%B8%80%E6%AC%A1%E8%B4%9F%E8%BD%BD%E7%AA%81%E5%A2%9E%22%5D%20--%3E%20PERF%5B%22performance%3A%20%E6%9C%AC%E6%9D%A5%E5%B0%B1%E9%92%89%E6%9C%80%E9%AB%98%E9%A2%91%22%5D%0A%20%20SPIKE%20--%3E%20SAVE%5B%22powersave%3A%20%E4%BB%8D%E9%92%89%E4%BD%8E%E9%A2%91%2C%20%E6%85%A2%E4%BD%86%E7%9C%81%22%5D%0A%20%20SPIKE%20--%3E%20ODD%5B%22ondemand%3A%20%E7%AD%89%E4%B8%8B%E4%B8%80%E4%B8%AA%E9%87%87%E6%A0%B7%E7%82%B9%E5%86%8D%E8%B7%B3%22%5D%0A%20%20SPIKE%20--%3E%20SCHED%5B%22schedutil%3A%20%E4%B8%8B%E6%AC%A1%E8%B0%83%E5%BA%A6%E6%9B%B4%E6%96%B0%E5%B0%B1%E8%B7%B3%22%5D%0A%20%20ODD%20--%3E%20LAG%5B%22%E9%87%87%E6%A0%B7%E9%97%B4%E9%9A%94%E5%8D%B3%E8%BF%87%E6%B8%A1%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">常见误区：初学者容易以为「钉低频一定省电」。实际上慢工未必出细活：跑得快能更早干完、更早降频甚至进空闲档，总能耗反而可能更低；一味压低频率还会把实时延迟指标（如 cyclictest 的 max）打爆。</span></p><p>容器一般不能直接设主机 freq，只能靠自己的 util 间接。</p><p>实现上：intel_pstate 在 passive 模式才听 schedutil。boost 受热墙限制，瞬时频率不是承诺。无 tick 的隔离核 util 更新少，governor 会看错忙闲。 读法上只引用<a href="/cs/fairness-metrics">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>cpufreq governor</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 thermal 框架的全部 trip。不保证虚拟化 pstate 是真硬件。下一课更闲时：C-state。</p><p>版本字段会变，课序钉的是机制对象「cpufreq governor」，不是某一主线内核的结构体名。 后课默认：频率由 governor 跟踪 util。空闲核进哪一档 C-state，下一课 cpuidle。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>governor 把 util 映射到 P-state。</li><li>schedutil 与调度器共用 util。</li><li>cpuidle/C-state 是下一课。</li><li>出处：Linux CPUFreq；ACPI；EAS 文档。</li></ul>',10))])}const P=E(u,[["render",B]]);export{D as __pageData,P as default};
